package com.bank.flink.backend;

import java.math.BigDecimal;
import java.util.HashMap;
import java.util.Map;
import java.util.logging.Logger;

// HashMapStateBackend analogue: plain objects on heap. Fast access,
// but checkpoint is a FULL snapshot proportional to total entries.
class HeapStateBackend implements StateBackend {
    private static final Logger log = Logger.getLogger(HeapStateBackend.class.getName());
    private final Map<String, BigDecimal> heap = new HashMap<>();

    @Override
    public void put(String accountId, BigDecimal value) {
        heap.put(accountId, value); // no serialization: instant
    }

    @Override
    public BigDecimal get(String accountId) {
        return heap.getOrDefault(accountId, BigDecimal.ZERO); // instant object read
    }

    @Override
    public long checkpoint() {
        // FULL snapshot: cost grows with TOTAL state size.
        long cost = heap.size();
        log.info(() -> "HEAP checkpoint = FULL snapshot of " + cost + " entries (cost " + cost + ")");
        return cost;
    }

    @Override
    public String name() { return "HashMapStateBackend"; }
}
