package com.bank.flink.backend;

import java.math.BigDecimal;
import java.util.HashMap;
import java.util.HashSet;
import java.util.Map;
import java.util.Set;
import java.util.logging.Logger;

// EmbeddedRocksDBStateBackend analogue: serialized bytes on disk. Access has
// serialization overhead, but checkpoints are INCREMENTAL (only changed keys).
class RocksDbStateBackend implements StateBackend {
    private static final Logger log = Logger.getLogger(RocksDbStateBackend.class.getName());
    private final Map<String, byte[]> disk = new HashMap<>();   // serialized bytes
    private final Set<String> dirtySinceCheckpoint = new HashSet<>();

    @Override
    public void put(String accountId, BigDecimal value) {
        disk.put(accountId, value.toPlainString().getBytes()); // serialize to bytes
        dirtySinceCheckpoint.add(accountId);                    // mark changed
    }

    @Override
    public BigDecimal get(String accountId) {
        byte[] bytes = disk.get(accountId);
        if (bytes == null) return BigDecimal.ZERO;
        return new BigDecimal(new String(bytes)); // deserialize: extra cost
    }

    @Override
    public long checkpoint() {
        // INCREMENTAL: cost grows only with CHANGED entries since last checkpoint.
        long cost = dirtySinceCheckpoint.size();
        log.info(() -> "ROCKSDB checkpoint = INCREMENTAL upload of " + cost
                + " changed entries (total on disk " + disk.size() + ", cost " + cost + ")");
        dirtySinceCheckpoint.clear();
        return cost;
    }

    @Override
    public String name() { return "EmbeddedRocksDBStateBackend"; }
}
