package com.bank.flink.backend;

import java.math.BigDecimal;
import java.util.logging.ConsoleHandler;
import java.util.logging.Formatter;
import java.util.logging.Level;
import java.util.logging.LogRecord;
import java.util.logging.Logger;

// Runnable demo: same workload through heap vs rocksdb, comparing
// access style and checkpoint cost (full vs incremental).
public class StateBackendDemo {
    private static final Logger log = Logger.getLogger(StateBackendDemo.class.getName());

    static {
        Logger root = Logger.getLogger("");
        for (var h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler handler = new ConsoleHandler();
        handler.setLevel(Level.ALL);
        handler.setFormatter(new BackendLogFormatter());
        root.addHandler(handler);
        root.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        runWorkload(new HeapStateBackend());
        runWorkload(new RocksDbStateBackend());
    }

    private static void runWorkload(StateBackend backend) {
        log.info(() -> "=== Backend: " + backend.name() + " ===");
        // Seed 1000 accounts (large existing state).
        for (int i = 0; i < 1000; i++) {
            backend.put("ACC" + i, new BigDecimal(i));
        }
        backend.checkpoint(); // first checkpoint

        // Now only 3 accounts change before the next checkpoint.
        backend.put("SAV2001", new BigDecimal("800"));
        backend.put("CUR3001", new BigDecimal("800"));
        backend.put("ACC42", new BigDecimal("999"));

        long cost = backend.checkpoint(); // second checkpoint
        log.info(() -> "SAV2001 balance = " + backend.get("SAV2001")
                + " | second-checkpoint cost = " + cost);
    }
}

// ─── Would be in BackendLogFormatter.java in a real project ───
class BackendLogFormatter extends Formatter {
    @Override
    public String format(LogRecord record) {
        return String.format("%1$tF %1$tT [%2$s] %3$s%n",
                new java.util.Date(record.getMillis()),
                record.getLevel().getName(),
                record.getMessage());
    }
}
